// openIdentityStore opens a Store on a fresh temp SQLite file (the
// internal/store test-helper shape — identity rides Store.DB(), so the
// accounts schema ships with Open) and closes it on cleanup.
func openIdentityStore(t *testing.T) *store.Store {
	t.Helper()
	dsn := filepath.Join(t.TempDir(), "test.db")
	s, err := store.Open(context.Background(), dsn)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	return s
}

// openIdentityService is the store plus a fixed clock (the injected now —
// deterministic stamps, no sleeping).
func openIdentityService(t *testing.T) *Service {
	t.Helper()
	stamp := time.Date(2026, 11, 4, 12, 0, 0, 0, time.UTC)
	return NewService(openIdentityStore(t), func() time.Time { return stamp })
}

// TestIdentityUserCRUD covers the user CRUD joint (task 3.1): create → get
// round-trip with lowercase normalization, duplicate-username refusal,
// role and disable set+get, the opaque prefs round-trip, and the password
// verify path (the stored argon2id hash verifies the plaintext and not a
// wrong password).
func TestIdentityUserCRUD(t *testing.T) {
	ctx := context.Background()

	t.Run("create_get_roundtrip_normalized", func(t *testing.T) {
		s := openIdentityService(t)
		u, err := s.Create(ctx, "  Alia  ", "correct horse battery staple")
		if err != nil {
			t.Fatalf("Create: %v", err)
		}
		if u.Username != "alia" {
			t.Fatalf("Create username = %q, want normalized %q", u.Username, "alia")
		}
		if u.Role != "user" || u.Disabled || u.Prefs != "{}" {
			t.Fatalf("Create defaults = role %q disabled %v prefs %q, want user/false/{}", u.Role, u.Disabled, u.Prefs)
		}
		if u.ID == 0 {
			t.Fatalf("Create id = 0, want the minted AUTOINCREMENT id")
		}
		// Mixed-case lookups land on the same normalized row.
		got, err := s.Get(ctx, "ALIA")
		if err != nil {
			t.Fatalf("Get: %v", err)
		}
		if got.ID != u.ID || got.Username != "alia" || got.Role != "user" || got.Disabled {
			t.Fatalf("Get = %+v, want the created row (normalized username, user, enabled)", got)
		}
		if got.CreatedAt.IsZero() || got.UpdatedAt.IsZero() {
			t.Fatalf("Get stamps = %v/%v, want both stamped", got.CreatedAt, got.UpdatedAt)
		}
	})

	t.Run("duplicate_username_refused", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "pw1"); err != nil {
			t.Fatalf("Create #1: %v", err)
		}
		// Same user in another case — normalization collides onto the UNIQUE row.
		if _, err := s.Create(ctx, "Alia", "pw2"); err == nil {
			t.Fatalf("Create duplicate = nil error, want the UNIQUE-constraint refusal")
		}
	})

	t.Run("empty_username_refused", func(t *testing.T) {
		s := openIdentityService(t)
		for _, name := range []string{"", "   "} {
			if _, err := s.Create(ctx, name, "pw"); err == nil {
				t.Fatalf("Create(%q) = nil error, want refusal", name)
			}
		}
	})

	t.Run("role_set_get", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("Create: %v", err)
		}
		if err := s.SetRole(ctx, "alia", "admin"); err != nil {
			t.Fatalf("SetRole admin: %v", err)
		}
		got, err := s.Get(ctx, "alia")
		if err != nil {
			t.Fatalf("Get: %v", err)
		}
		if got.Role != "admin" {
			t.Fatalf("Role = %q, want admin", got.Role)
		}
		if err := s.SetRole(ctx, "alia", "user"); err != nil {
			t.Fatalf("SetRole user: %v", err)
		}
		if got, _ = s.Get(ctx, "alia"); got.Role != "user" {
			t.Fatalf("Role = %q, want user", got.Role)
		}
		// Unknown roles refuse before the database sees them.
		if err := s.SetRole(ctx, "alia", "root"); err == nil {
			t.Fatalf("SetRole root = nil error, want refusal")
		}
	})

	t.Run("disable_set_get", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("Create: %v", err)
		}
		if err := s.SetDisabled(ctx, "alia", true); err != nil {
			t.Fatalf("SetDisabled true: %v", err)
		}
		got, err := s.Get(ctx, "alia")
		if err != nil {
			t.Fatalf("Get: %v", err)
		}
		if !got.Disabled {
			t.Fatalf("Disabled = false, want true")
		}
		if err := s.SetDisabled(ctx, "alia", false); err != nil {
			t.Fatalf("SetDisabled false: %v", err)
		}
		if got, _ = s.Get(ctx, "alia"); got.Disabled {
			t.Fatalf("Disabled = true, want false")
		}
	})

	t.Run("prefs_roundtrip_opaque", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("Create: %v", err)
		}
		doc := `{"theme":"dark","row":3}`
		if err := s.SetPrefs(ctx, "alia", doc); err != nil {
			t.Fatalf("SetPrefs: %v", err)
		}
		got, err := s.Get(ctx, "alia")
		if err != nil {
			t.Fatalf("Get: %v", err)
		}
		if got.Prefs != doc {
			t.Fatalf("Prefs = %q, want verbatim %q (opaque passthrough)", got.Prefs, doc)
		}
	})

	t.Run("password_verify_path", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "correct horse"); err != nil {
			t.Fatalf("Create: %v", err)
		}
		got, err := s.Get(ctx, "alia")
		if err != nil {
			t.Fatalf("Get: %v", err)
		}
		if !strings.HasPrefix(got.PasswordHash, "$argon2id$v=19$m=65536,t=1,p=1$") {
			t.Fatalf("PasswordHash = %q, want the pinned argon2id PHC header", got.PasswordHash)
		}
		ok, err := s.VerifyPassword(ctx, "alia", "correct horse")
		if err != nil || !ok {
			t.Fatalf("VerifyPassword(correct) = %v, %v; want true, nil", ok, err)
		}
		ok, err = s.VerifyPassword(ctx, "alia", "wrong horse")
		if err != nil || ok {
			t.Fatalf("VerifyPassword(wrong) = %v, %v; want false, nil", ok, err)
		}
		// Unknown user is indistinguishable from a wrong password (no
		// enumeration) — (false, nil) both ways.
		ok, err = s.VerifyPassword(ctx, "nobody", "correct horse")
		if err != nil || ok {
			t.Fatalf("VerifyPassword(unknown) = %v, %v; want false, nil", ok, err)
		}
	})

	t.Run("password_reset_rehash", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "old pw"); err != nil {
			t.Fatalf("Create: %v", err)
		}
		if err := s.ResetPassword(ctx, "alia", "new pw"); err != nil {
			t.Fatalf("ResetPassword: %v", err)
		}
		ok, err := s.VerifyPassword(ctx, "alia", "new pw")
		if err != nil || !ok {
			t.Fatalf("VerifyPassword(new) = %v, %v; want true, nil", ok, err)
		}
		ok, err = s.VerifyPassword(ctx, "alia", "old pw")
		if err != nil || ok {
			t.Fatalf("VerifyPassword(old) = %v, %v; want false, nil (rehashed)", ok, err)
		}
	})

	t.Run("unknown_user_is_no_rows", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Get(ctx, "nobody"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("Get(nobody) = %v, want the wrapped unknown-user (sql.ErrNoRows) error", err)
		}
		if err := s.SetRole(ctx, "nobody", "admin"); !strings.Contains(err.Error(), "unknown user") {
			t.Fatalf("SetRole(nobody) = %v, want the unknown-user error", err)
		}
	})
}

// TestIdentityLastUserGuard covers the last-user joint (task 3.1): the sole
// user's delete refuses with ErrLastUser; a second user makes the first
// deletable; then the remaining last user refuses again.
func TestIdentityLastUserGuard(t *testing.T) {
	ctx := context.Background()

	s := openIdentityService(t)
	if _, err := s.Create(ctx, "sole", "pw"); err != nil {
		t.Fatalf("Create sole: %v", err)
	}
	if err := s.DeleteUser(ctx, "sole"); !errors.Is(err, ErrLastUser) {
		t.Fatalf("DeleteUser(sole) = %v, want ErrLastUser", err)
	}

	if _, err := s.Create(ctx, "second", "pw"); err != nil {
		t.Fatalf("Create second: %v", err)
	}
	// Two users: either is deletable.
	if err := s.DeleteUser(ctx, "sole"); err != nil {
		t.Fatalf("DeleteUser(sole with second present) = %v, want nil", err)
	}
	if _, err := s.Get(ctx, "sole"); !strings.Contains(err.Error(), "unknown user") {
		t.Fatalf("Get(deleted) = %v, want the unknown-user error", err)
	}

	// Back to one user: the guard re-arms.
	if err := s.DeleteUser(ctx, "second"); !errors.Is(err, ErrLastUser) {
		t.Fatalf("DeleteUser(last remaining) = %v, want ErrLastUser", err)
	}
	if _, err := s.Get(ctx, "second"); err != nil {
		t.Fatalf("Get(second after refused delete) = %v, want the row intact", err)
	}

	// The guard never aliasing an unknown user into ErrLastUser: deleting a
	// user that never existed while others survive is the unknown-user error.
	if _, err := s.Create(ctx, "third", "pw"); err != nil {
		t.Fatalf("Create third: %v", err)
	}
	if err := s.DeleteUser(ctx, "ghost"); !strings.Contains(err.Error(), "unknown user") || errors.Is(err, ErrLastUser) {
		t.Fatalf("DeleteUser(ghost) = %v, want the unknown-user error, not ErrLastUser", err)
	}
}

// TestIdentityUserByID covers the by-id reader (task 8.1): the profile
// surface knows its caller only as Principal.UserID, so the row must
// round-trip by id — every fact intact — and an unknown id surfaces the
// wrapped unknown-user error (handlers map to 404).
func TestIdentityUserByID(t *testing.T) {
	s := openIdentityService(t)
	ctx := context.Background()

	u, err := s.Create(ctx, "alia", "pw")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if err := s.SetRole(ctx, "alia", "admin"); err != nil {
		t.Fatalf("SetRole: %v", err)
	}
	if err := s.SetPrefs(ctx, "alia", `{"auto_next":false}`); err != nil {
		t.Fatalf("SetPrefs: %v", err)
	}

	byID, err := s.UserByID(ctx, u.ID)
	if err != nil {
		t.Fatalf("UserByID: %v", err)
	}
	if byID.ID != u.ID || byID.Username != "alia" || byID.Role != "admin" {
		t.Fatalf("UserByID = {id %d, name %q, role %q}, want the row's facts", byID.ID, byID.Username, byID.Role)
	}
	if byID.Prefs != `{"auto_next":false}` {
		t.Fatalf("UserByID prefs = %q, want the stored document verbatim", byID.Prefs)
	}
	if _, err := s.UserByID(ctx, u.ID+42); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("UserByID(unknown) = %v, want wrapped sql.ErrNoRows", err)
	}
}
